import { createDocumentHandler } from "@/lib/artifacts/server";
import { encodeAudioRef } from "@/lib/audio/ref";

/**
 * Audio is never generated by the model.
 *
 * Every audio document is a file the user attached, so the streaming callbacks
 * hand the client a descriptor and the studio does the rest.
 */
export const audioDocumentHandler = createDocumentHandler<"audio">({
  kind: "audio",
  onCreateDocument: ({ dataStream, title }) => {
    const content = encodeAudioRef({ storageKey: "", title });

    dataStream.write({
      data: content,
      transient: true,
      type: "data-audioDelta",
    });

    return Promise.resolve(content);
  },
  onUpdateDocument: ({ document, dataStream }) => {
    const content = document.content ?? encodeAudioRef({ storageKey: "" });

    dataStream.write({
      data: content,
      transient: true,
      type: "data-audioDelta",
    });

    return Promise.resolve(content);
  },
});
